new file mode 100644
index 0000000..3d56888
--- /dev/null
+++ b/actions/admin/image.ts
@@ -0,0 +1,55 @@
+'use server';
+
+import type { RequestStatus } from '@prisma/client';
+
+import prisma from '@/lib/prisma';
+import { currentUser } from '@/lib/auth';
+import { checkCurrentUserPermission } from '@/data/admin/permissions';
+import { ERROR_IDS } from '@/constants/errorIds';
+
+/**
+ * 管理員更新圖片 NSFW 狀態（需 write-imageManagement 權限）
+ */
+export async function updateImageNsfwByAdmin(imageId: string, isNsfw: boolean) {
+  const user = await currentUser();
+  if (!user?.id) {
+    throw new Error(ERROR_IDS.LOGIN_REQUIRED);
+  }
+
+  const hasPermission = await checkCurrentUserPermission(
+    'write-imageManagement'
+  );
+  if (!hasPermission) {
+    throw new Error(ERROR_IDS.NO_PERMISSION);
+  }
+
+  return await prisma.image.update({
+    where: { id: imageId },
+    data: { isNsfw }
+  });
+}
+
+/**
+ * 管理員更新生圖紀錄的生成狀態（需 write-imageManagement 權限）
+ */
+export async function updateImageGenerationStatusByAdmin(
+  imageGenerationId: string,
+  requestStatus: RequestStatus
+) {
+  const user = await currentUser();
+  if (!user?.id) {
+    throw new Error(ERROR_IDS.LOGIN_REQUIRED);
+  }
+
+  const hasPermission = await checkCurrentUserPermission(
+    'write-imageManagement'
+  );
+  if (!hasPermission) {
+    throw new Error(ERROR_IDS.NO_PERMISSION);
+  }
+
+  return await prisma.imageGeneration.update({
+    where: { id: imageGenerationId },
+    data: { requestStatus }
+  });
+}
