+
+  const coverUrl = webtoon.cover?.rawUrl ?? webtoon.cover?.url;
+  const isDeleted = !!webtoon.deletedAt;
+
+  const visibilityMutation = useMutation({
+    mutationFn: async (isPublic: boolean) => {
+      return await updateWebtoonVisibilityByAdmin(webtoon.id, isPublic);
+    },
+    onSuccess: () => {
+      queryClient.invalidateQueries({ queryKey: ['admin-webtoons'] });
+      toast.success(t('artwork.visibility.success'));
+    },
+    onError: (error) => {
+      console.error('Error updating webtoon visibility:', error);
+      toast.error(t('artwork.visibility.error'));
+    }
+  });
+
+  const handleVisibilityChange = (isPublic: boolean) => {
+    visibilityMutation.mutate(isPublic);
+  };
+
+  const handleDeleteSuccess = () => {
+    queryClient.invalidateQueries({ queryKey: ['admin-webtoons'] });
+  };
+
+  const publicUrl = `/webtoons/${webtoon.id}`;
