+
+  const { ref: loadMoreRef, inView } = useInView({ threshold: 0 });
+  const { ref: bottomSentinelRef, inView: isAtBottom } = useInView({
+    threshold: 0
+  });
+  const {
+    data: slicesData,
+    fetchNextPage,
+    hasNextPage,
+    isFetchingNextPage,
+    isLoading: isSlicesLoading
+  } = useInfiniteQuery({
+    queryKey: ['admin-webtoon-slices', webtoon.id],
+    queryFn: async ({ pageParam }) => {
+      const params = new URLSearchParams({
+        webtoonId: webtoon.id,
+        take: '20'
+      });
+      if (pageParam) params.set('cursor', pageParam as string);
+      const res = await fetch(`/api/webtoon-slice?${params.toString()}`);
+      if (!res.ok) throw new Error('Failed to fetch slices');
+      return res.json() as Promise<{
+        data: WebtoonSliceItem[];
+        cursor?: string;
+      }>;
+    },
+    getNextPageParam: (lastPage) => lastPage.cursor,
+    initialPageParam: undefined as string | undefined,
+    enabled: isDialogOpen && !!webtoon.id
+  });
+
+  useEffect(() => {
+    if (inView && hasNextPage && !isFetchingNextPage) {
+      fetchNextPage();
+    }
+  }, [inView, hasNextPage, isFetchingNextPage, fetchNextPage]);
+
+  const allSlices: WebtoonSliceItem[] =
