+import { useTranslations } from 'next-intl';
+import { format } from 'date-fns';
+
+import type { AdminWebtoon } from '@/data/admin/webtoon';
+
+import { LoadingSkeleton } from '../../images/_components/loading-skeleton';
+import { EmptyState } from '../../images/_components/empty-state';
+
+import { WebtoonCard } from './webtoon-card';
+
+interface WebtoonsContentProps {
+  isLoading: boolean;
+  groupedWebtoons: Record<string, AdminWebtoon[]>;
+  showNsfw: boolean;
+  searchTerm?: string;
+  onAddUserToFilter?: (userId: string) => void;
+}
+
+export function WebtoonsContent({
+  isLoading,
+  groupedWebtoons,
+  showNsfw,
+  searchTerm,
+  onAddUserToFilter
+}: WebtoonsContentProps) {
+  const t = useTranslations();
+
+  if (isLoading) {
+    return <LoadingSkeleton />;
+  }
+
+  if (Object.keys(groupedWebtoons).length === 0) {
+    return (
+      <EmptyState
+        message={t('admin.webtoons.noWebtoonsFound', {
+          defaultMessage: '找不到條漫'
+        })}
+      />
+    );
+  }
+
+  return (
+    <>
+      {Object.entries(groupedWebtoons).map(([date, webtoonsOnDate]) => (
+        <div key={date} className="mb-8">
+          <h2 className="flex items-center text-xl font-semibold mb-4 border-b pb-2">
+            {format(new Date(date), 'MMMM d, yyyy')}
+            <span className="rounded-full bg-yellow-500 text-xs font-normal text-white px-2 py-1 ml-2">
+              {webtoonsOnDate.length}
+            </span>
+          </h2>
+          <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 xl:grid-cols-8 gap-4">
+            {webtoonsOnDate.map((webtoon) => (
+              <WebtoonCard
+                key={`webtoon-admin-${webtoon.id}`}
+                webtoon={webtoon}
+                showNsfw={showNsfw}
+                searchTerm={searchTerm}
+                onAddUserToFilter={onAddUserToFilter}
+              />
+            ))}
+          </div>
+        </div>
+      ))}
+    </>
+  );
+}
