+'use client';
+
+import { useState } from 'react';
+import { useTranslations } from 'next-intl';
+import { AssetType } from '@prisma/client';
+import { toast } from 'sonner';
+
+import {
+  Dialog,
+  DialogContent,
+  DialogDescription,
+  DialogFooter,
+  DialogHeader,
+  DialogTitle
+} from '@/components/ui/dialog';
+import { Button } from '@/components/ui/button';
+import { removeAsset } from '@/actions/moderation';
+
+type DeleteWebtoonDialogProps = {
+  isOpen: boolean;
+  onOpenChange: (open: boolean) => void;
+  webtoonId: string;
+  webtoonName: string;
+  onSuccess?: () => void;
+};
+
+export function DeleteWebtoonDialog({
+  isOpen,
+  onOpenChange,
+  webtoonId,
+  webtoonName,
+  onSuccess
+}: DeleteWebtoonDialogProps) {
+  const t = useTranslations();
+  const [isDeleting, setIsDeleting] = useState(false);
+
+  const handleDelete = async () => {
+    try {
+      setIsDeleting(true);
+      await removeAsset({
+        assetId: webtoonId,
+        assetType: AssetType.WEBTOON
+      });
+      toast.success(
+        t('admin.webtoons.deleteSuccess', {
+          defaultMessage: '條漫已刪除'
+        })
+      );
+      onSuccess?.();
+      onOpenChange(false);
+    } catch (error) {
+      console.error('Error deleting webtoon:', error);
+      toast.error(
+        t('admin.webtoons.deleteError', {
+          defaultMessage: '刪除條漫時發生錯誤'
+        })
+      );
+    } finally {
+      setIsDeleting(false);
+    }
+  };
+
+  return (
+    <Dialog open={isOpen} onOpenChange={onOpenChange}>
+      <DialogContent>
+        <DialogHeader>
+          <DialogTitle>
+            {t('admin.webtoons.deleteConfirmTitle', {
+              defaultMessage: '確認刪除條漫'
+            })}
+          </DialogTitle>
+          <DialogDescription>
+            {t('admin.webtoons.deleteConfirmMessage', {
+              webtoonName,
+              defaultMessage: `您確定要刪除條漫「${webtoonName}」嗎？此操作無法復原，並且會發送通知郵件給條漫擁有者。`
+            })}
+          </DialogDescription>
+        </DialogHeader>
+        <DialogFooter>
+          <Button
+            variant="outline"
+            onClick={() => onOpenChange(false)}
+            disabled={isDeleting}
+          >
+            {t('common.button.cancel', { defaultMessage: '取消' })}
+          </Button>
+          <Button
+            variant="destructive"
+            onClick={handleDelete}
+            disabled={isDeleting}
+          >
+            {isDeleting
+              ? t('common.button.deleting', { defaultMessage: '刪除中...' })
+              : t('common.button.delete', { defaultMessage: '刪除' })}
+          </Button>
+        </DialogFooter>
+      </DialogContent>
+    </Dialog>
+  );
+}
